#include <windows.h>
#include <dbghelp.h>
#include <fstream>
#include <filesystem>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
#pragma comment(lib, "dbghelp.lib")

// Profiles only the private child launched here. No system tracing or process attach.
int wmain(int argc, wchar_t** argv) {
    if (argc < 4) return 2;
    std::wstring command = L"\"" + std::wstring(argv[2]) + L"\"";
    for (int i = 3; i < argc; ++i) command += L" \"" + std::wstring(argv[i]) + L"\"";
    std::vector<wchar_t> buffer(command.begin(), command.end()); buffer.push_back(0);
    STARTUPINFOW startup{}; startup.cb = sizeof(startup);
    PROCESS_INFORMATION process{};
    if (!CreateProcessW(argv[2], buffer.data(), nullptr, nullptr, FALSE, CREATE_NO_WINDOW, nullptr, nullptr, &startup, &process)) {
        std::cerr << "CreateProcess error " << GetLastError() << "\n"; return 3;
    }
    Sleep(100);
    SymSetOptions(SYMOPT_DEFERRED_LOADS | SYMOPT_UNDNAME | SYMOPT_LOAD_LINES | SYMOPT_FAIL_CRITICAL_ERRORS);
    if (!SymInitializeW(process.hProcess, std::filesystem::path(argv[2]).parent_path().c_str(), TRUE)) {
        std::cerr << "SymInitialize error " << GetLastError() << "\n";
        TerminateProcess(process.hProcess, 4); WaitForSingleObject(process.hProcess, INFINITE);
        CloseHandle(process.hThread); CloseHandle(process.hProcess); return 4;
    }
    std::map<DWORD64, std::string> symbols;
    std::map<std::string, unsigned long> samples;
    unsigned long captured = 0, failed = 0;
    ULONG64 previous_cycles = 0; QueryThreadCycleTime(process.hThread, &previous_cycles);
    while (WaitForSingleObject(process.hProcess, 0) == WAIT_TIMEOUT) {
        ULONG64 cycles = 0; QueryThreadCycleTime(process.hThread, &cycles);
        if (cycles == previous_cycles) { Sleep(1); continue; }
        previous_cycles = cycles;
        std::vector<DWORD64> addresses;
        if (SuspendThread(process.hThread) != DWORD(-1)) {
            CONTEXT context{}; context.ContextFlags = CONTEXT_FULL;
            if (GetThreadContext(process.hThread, &context)) {
                STACKFRAME64 frame{};
                frame.AddrPC.Offset = context.Rip;
                frame.AddrFrame.Offset = context.Rbp;
                frame.AddrStack.Offset = context.Rsp;
                frame.AddrPC.Mode = frame.AddrFrame.Mode = frame.AddrStack.Mode = AddrModeFlat;
                addresses.push_back(context.Rip);
                for (int depth = 0; depth < 63; ++depth) {
                    if (!StackWalk64(IMAGE_FILE_MACHINE_AMD64, process.hProcess, process.hThread, &frame, &context, nullptr, SymFunctionTableAccess64, SymGetModuleBase64, nullptr) || !frame.AddrPC.Offset) break;
                    if (!addresses.empty() && addresses.back() == frame.AddrPC.Offset) continue;
                    addresses.push_back(frame.AddrPC.Offset);
                }
            } else ++failed;
            ResumeThread(process.hThread);
        } else ++failed;
        if (!addresses.empty()) {
            std::ostringstream stack;
            for (auto address : addresses) {
                auto found = symbols.find(address);
                if (found == symbols.end()) {
                    char storage[sizeof(SYMBOL_INFO) + MAX_SYM_NAME]{};
                    auto info = reinterpret_cast<SYMBOL_INFO*>(storage);
                    info->SizeOfStruct = sizeof(SYMBOL_INFO); info->MaxNameLen = MAX_SYM_NAME;
                    DWORD64 displacement = 0;
                    std::ostringstream text;
                    if (SymFromAddr(process.hProcess, address, &displacement, info)) text << info->Name;
                    else text << "0x" << std::hex << address;
                    IMAGEHLP_LINE64 line{}; line.SizeOfStruct = sizeof(line); DWORD line_offset = 0;
                    if (SymGetLineFromAddr64(process.hProcess, address, &line_offset, &line)) text << " [" << line.FileName << ":" << line.LineNumber << "]";
                    found = symbols.emplace(address, text.str()).first;
                }
                if (stack.tellp() > 0) stack << ";";
                stack << found->second;
            }
            ++samples[stack.str()]; ++captured;
        }
        Sleep(1);
    }
    DWORD code = 0; GetExitCodeProcess(process.hProcess, &code);
    std::ofstream output(argv[1]);
    for (auto& sample : samples) output << sample.second << "\t" << sample.first << "\n";
    std::cerr << "samples=" << captured << " failed=" << failed << " exit=" << code << "\n";
    SymCleanup(process.hProcess); CloseHandle(process.hThread); CloseHandle(process.hProcess);
    return int(code);
}
